local HatCrownBlockMaker = {}
local PRODUCTS = {
    iron_hatcrownblock = { name = "Železni krona za klobuke", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni krona za klobuke za klobucarje." },
    bronze_hatcrownblock = { name = "Bronast krona za klobuke", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast krona za klobuke za klobucarje." },
    silver_hatcrownblock = { name = "Srebrn krona za klobuke", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn krona za klobuke za klobucarje." },
    gilded_hatcrownblock = { name = "Pozlačen krona za klobuke", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen krona za klobuke za klobucarje." },
    jewel_set_hatcrownblock = { name = "Draguljast krona za klobuke", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast krona za klobuke za klobucarje." },
    royal_sovereign_hatcrownblock = { name = "Kraljevski suveren krona za klobuke", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren krona za klobuke z biseri za krono." },
}
local BUILDINGS = {
    hatcrownblock_workshop = { name = "Hatcrownblock delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    hatcrownblock_house = { name = "Hatcrownblock hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_hatcrownblock_atelier = { name = "Mojstrski hatcrownblock atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_hatcrownblock_palace = { name = "Suverena hatcrownblock palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
HatCrownBlockMaker.ironStock = 10; HatCrownBlockMaker.bronzeStock = 8; HatCrownBlockMaker.woodStock = 20; HatCrownBlockMaker.leatherStock = 10; HatCrownBlockMaker.silverStock = 8; HatCrownBlockMaker.goldStock = 6; HatCrownBlockMaker.jewelStock = 4; HatCrownBlockMaker.pearlStock = 4
HatCrownBlockMaker.productStock = {}; HatCrownBlockMaker.buildings = {}; HatCrownBlockMaker.maker = nil; HatCrownBlockMaker.activeMaking = {}; HatCrownBlockMaker.totalProducts = 0; HatCrownBlockMaker.dayTimer = 0
function HatCrownBlockMaker.init() HatCrownBlockMaker.ironStock=10; HatCrownBlockMaker.bronzeStock=8; HatCrownBlockMaker.woodStock=20; HatCrownBlockMaker.leatherStock=10; HatCrownBlockMaker.silverStock=8; HatCrownBlockMaker.goldStock=6; HatCrownBlockMaker.jewelStock=4; HatCrownBlockMaker.pearlStock=4; HatCrownBlockMaker.productStock={}; HatCrownBlockMaker.buildings={}; HatCrownBlockMaker.maker=nil; HatCrownBlockMaker.activeMaking={}; HatCrownBlockMaker.totalProducts=0; HatCrownBlockMaker.dayTimer=0; print("[HatCrownBlockMaker] Royal Hat Crown Block Maker System initialized (6 products, 4 buildings)") end
function HatCrownBlockMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HatCrownBlockMaker.maker={name=n or ("Kronar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kronar najet: %s (spretnost: %d)",HatCrownBlockMaker.maker.name,s),"success") end; return true end
function HatCrownBlockMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HatCrownBlockMaker.build(id) local ok,e=HatCrownBlockMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HatCrownBlockMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HatCrownBlockMaker.getQualityBonus() local b=0; for _,bd in ipairs(HatCrownBlockMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HatCrownBlockMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HatCrownBlockMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HatCrownBlockMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HatCrownBlockMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HatCrownBlockMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HatCrownBlockMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HatCrownBlockMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HatCrownBlockMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HatCrownBlockMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HatCrownBlockMaker.buildings==0 then return false,"Potrebna kronska delavnica" end; if not HatCrownBlockMaker.maker then return false,"Potreben kronar" end; return true end
function HatCrownBlockMaker.make(pt,qty) qty=qty or 1; local ok,e=HatCrownBlockMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HatCrownBlockMaker.ironStock=HatCrownBlockMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HatCrownBlockMaker.bronzeStock=HatCrownBlockMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HatCrownBlockMaker.woodStock=HatCrownBlockMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HatCrownBlockMaker.leatherStock=HatCrownBlockMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HatCrownBlockMaker.silverStock=HatCrownBlockMaker.silverStock-d.silverCost*qty end; if d.goldCost then HatCrownBlockMaker.goldStock=HatCrownBlockMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HatCrownBlockMaker.jewelStock=HatCrownBlockMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HatCrownBlockMaker.pearlStock=HatCrownBlockMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HatCrownBlockMaker.maker then t=math.max(1,t-math.floor(HatCrownBlockMaker.maker.skill/13)) end; table.insert(HatCrownBlockMaker.activeMaking,{id="hatcrownblock_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HatCrownBlockMaker.completeMaking(m) local q=1.0+(HatCrownBlockMaker.getQualityBonus()/100); if HatCrownBlockMaker.maker then q=q+(HatCrownBlockMaker.maker.skill/140) end; q=math.min(2.5,q); HatCrownBlockMaker.productStock[m.productType]=(HatCrownBlockMaker.productStock[m.productType] or 0)+m.quantity; HatCrownBlockMaker.totalProducts=HatCrownBlockMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HatCrownBlockMaker.maker then HatCrownBlockMaker.maker.itemsMade=HatCrownBlockMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HatCrownBlockMaker.maker.skill=math.min(100,HatCrownBlockMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krona izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hatcrownblock.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HatCrownBlockMaker.update(dt) if not _G.state then return end; HatCrownBlockMaker.dayTimer=HatCrownBlockMaker.dayTimer+dt; if HatCrownBlockMaker.dayTimer>=30 then HatCrownBlockMaker.dayTimer=0; for i=#HatCrownBlockMaker.activeMaking,1,-1 do local m=HatCrownBlockMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HatCrownBlockMaker.completeMaking(m); table.remove(HatCrownBlockMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HatCrownBlockMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HatCrownBlockMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HatCrownBlockMaker.getStats() return {ironStock=HatCrownBlockMaker.ironStock,bronzeStock=HatCrownBlockMaker.bronzeStock,woodStock=HatCrownBlockMaker.woodStock,leatherStock=HatCrownBlockMaker.leatherStock,silverStock=HatCrownBlockMaker.silverStock,goldStock=HatCrownBlockMaker.goldStock,jewelStock=HatCrownBlockMaker.jewelStock,pearlStock=HatCrownBlockMaker.pearlStock,productStock=HatCrownBlockMaker.productStock,numBuildings=#HatCrownBlockMaker.buildings,hasMaker=HatCrownBlockMaker.maker~=nil,makerName=HatCrownBlockMaker.maker and HatCrownBlockMaker.maker.name or "—",makerSkill=HatCrownBlockMaker.maker and HatCrownBlockMaker.maker.skill or 0,activeMaking=#HatCrownBlockMaker.activeMaking,totalProducts=HatCrownBlockMaker.totalProducts} end
return HatCrownBlockMaker
